const NOW = '2026-07-18T12:00:00.000Z';
const NEXT_MONTH = '2026-08-18T12:00:00.000Z';

function entryContext(overrides) {
  return {
    id: `entry-${overrides.id}`,
    propertyId: `property-${overrides.id}`,
    userId: `user-${overrides.id}`,
    entryPath: overrides.entryPath,
    ownershipState: overrides.ownershipState,
    propertyOrigin: overrides.propertyOrigin,
    activeTrigger: {
      type: overrides.triggerType,
      label: overrides.triggerLabel,
      detail: overrides.triggerDetail ?? null,
      entityType: overrides.entityType ?? 'PROPERTY',
      entityId: overrides.entityId ?? null,
      identifiedAt: NOW,
      source: overrides.triggerSource ?? 'USER_SELECTED',
    },
    firstValue: {
      type: overrides.firstValueType ?? 'TRIGGER_GUIDANCE',
      deliveredAt: null,
      firstActionResolvedAt: null,
    },
    contextVersion: 'phase0-v1',
    consentContext: null,
    createdAt: NOW,
    updatedAt: NOW,
  };
}

function governance(overrides = {}) {
  const commercial = overrides.commercial === true;
  return {
    safetyTier: overrides.safetyTier ?? 'LOW_CONSEQUENCE',
    professionalBoundary: overrides.professionalBoundary ?? null,
    jurisdictionCheck: {
      status: overrides.jurisdictionStatus ?? 'NOT_REQUIRED',
      jurisdiction: overrides.jurisdiction ?? null,
      checkedAt: overrides.jurisdictionStatus === 'VERIFIED' ? NOW : null,
      source: overrides.jurisdictionStatus === 'VERIFIED' ? 'Reviewed fixture policy' : null,
    },
    conservativeFallback: overrides.conservativeFallback ?? null,
    emergencyEscalation: overrides.emergencyEscalation ?? null,
    commercialDisclosure: {
      involvesCommercialAction: commercial,
      relationshipType: commercial ? (overrides.relationshipType ?? 'NONE') : 'NONE',
      compensationMayOccur: commercial ? Boolean(overrides.compensationMayOccur) : false,
      rankingInfluenced: commercial ? Boolean(overrides.rankingInfluenced) : false,
      summary: commercial
        ? (overrides.commercialSummary ?? 'No compensation or ownership relationship affects this fixture ranking.')
        : 'No commercial action is presented in this recommendation.',
      selectionCriteria: commercial ? ['Scope fit', 'Credential status', 'Availability'] : [],
      nonCommercialAlternatives: commercial ? ['Use a provider you already trust'] : [],
    },
    reviewedBy: [],
    policyVersion: 'phase0-v1',
  };
}

function action(overrides) {
  const material = overrides.safetyTier === 'MATERIAL_FINANCIAL' ||
    overrides.safetyTier === 'REGULATED_COVERAGE';
  const primaryKind = overrides.primaryCtaKind ?? 'REVIEW';
  return {
    id: `action-${overrides.id}`,
    propertyId: `property-${overrides.id}`,
    lineageId: `lineage-${overrides.id}`,
    source: {
      kind: overrides.sourceKind ?? 'GUIDANCE',
      entityId: `source-${overrides.id}`,
      version: '1.0.0',
    },
    job: overrides.job ?? 'STAY_AHEAD',
    state: 'OPEN',
    priority: overrides.priority ?? 'SOON',
    signal: overrides.signal,
    whyItMatters: overrides.whyItMatters,
    recommendedAction: overrides.recommendedAction,
    expectedOutcome: overrides.expectedOutcome,
    timing: {
      dueAt: overrides.dueAt ?? NEXT_MONTH,
      windowStart: NOW,
      windowEnd: overrides.dueAt ?? NEXT_MONTH,
      rationale: overrides.timingRationale ?? 'Act within the recommended window while options remain available.',
    },
    evidence: [{
      id: `evidence-${overrides.id}`,
      type: overrides.evidenceType ?? 'USER_INPUT',
      label: overrides.evidenceLabel ?? 'Homeowner-provided context',
      source: overrides.evidenceSource ?? 'Golden test fixture',
      observedAt: NOW,
      freshness: overrides.evidenceFreshness ?? 'CURRENT',
      confidence: overrides.evidenceConfidence ?? 0.8,
    }],
    assumptions: material ? [{
      key: 'scope_assumption',
      label: 'Work scope',
      value: overrides.assumption ?? 'The described scope is complete.',
      source: 'USER',
      editable: true,
    }] : [],
    options: material ? [
      { id: 'act-now', label: 'Act now', summary: 'Proceed using the verified scope.', recommended: true },
      { id: 'wait', label: 'Wait', summary: 'Delay and monitor the stated trigger.', recommended: false },
    ] : [],
    tradeoffs: material ? [{
      optionId: 'act-now',
      dimension: 'COST',
      summary: 'Acting now costs more immediately but can limit further exposure.',
    }] : [],
    confidence: {
      score: overrides.confidenceScore ?? 0.8,
      label: overrides.confidenceLabel ?? 'HIGH',
      missing: overrides.missing ?? [],
    },
    governance: governance({
      safetyTier: overrides.safetyTier,
      professionalBoundary: material
        ? 'This guidance supports homeowner decision-making and is not a binding professional estimate.'
        : null,
      jurisdictionStatus: overrides.jurisdictionStatus,
      jurisdiction: overrides.jurisdiction,
      conservativeFallback: overrides.conservativeFallback,
      emergencyEscalation: overrides.emergencyEscalation,
      commercial: ['SELECT_PROVIDER', 'PURCHASE', 'FINANCE'].includes(primaryKind),
    }),
    primaryCta: {
      kind: primaryKind,
      label: overrides.primaryCtaLabel ?? 'Review recommendation',
      href: `/dashboard/properties/property-${overrides.id}`,
    },
    secondaryCtas: [],
    feedbackControls: ['COMPLETE', 'DEFER', 'SNOOZE', 'DISMISS', 'NOT_RELEVANT', 'CORRECT_FACT'],
    relatedJourneyId: overrides.relatedJourneyId ?? null,
    createdAt: NOW,
    lastEvaluatedAt: NOW,
  };
}

